"""Tactics in league terms: attack through the middle or the edges, kicking game, line speed, the ruck, shape and tempo."""
import re

def apply(js, rep, resub, replace_function):
    for old, new in (('Forwards', 'Middle'), ('Backs', 'Edges'), ('Drift', 'Slide'), ('Compete', 'Wrestle'), ('Fan out', 'Get back')):
        js = resub(js, r"(?<=['\":])" + re.escape(old) + r"(?=')", new, None, 'opt-' + old)
    js = rep(js, "attack:t.focus==='Middle'?'Middle':t.focus==='Edges'||t.shape==='Expansive'?'Edges':'Balanced'", "attack:'Balanced'")
    js = resub(js, r"^const TACTIC_AXES=.*$", lambda m: "const TACTIC_AXES={attack:'Attack focus',kicking:'Kicking game',defence:'Line speed',breakdown:'Ruck',shape:'Attack shape',tempo:'Set tempo'};", 1, 'axes', re.M)
    js = resub(js, r"^const TACTIC_INFO=.*$", lambda m: TACTIC_INFO, 1, 'info', re.M)
    js = replace_function(js, 'optionName', OPTION_NAME, 'optionname')
    js = replace_function(js, 'planEffects', PLAN_EFFECTS, 'planeffects')
    js = resub(js, r"^const RIVALRIES=.*$", lambda m: RIVALRIES, 1, 'rivalries', re.M)
    js = resub(js, r"^function displayTeam\(t\).*$", lambda m: DISPLAY, 1, 'display', re.M)
    js = rep(js, "// Rival coaches' staff: better clubs tend to have better coaches.", "// Rival coaches' staff: better clubs tend to have better coaches.")
    return js

TACTIC_INFO = r"""const TACTIC_INFO={'shape:Direct':{does:'Hit it up through the middle: one-out runners, tight carries close to the ruck and a physical, gain-line game.',best:'Your middle forwards outweigh theirs, or they get back and leave the ruck soft.',risk:'Fast line speed meets your carriers behind the advantage line, and a side that wrestles hard slows every play-the-ball.'},'shape:Balanced':{does:'Mix the middle and the edges depending on what is on.',best:'You have no clear edge in the middle or out wide.',risk:'Leaves your biggest strength under-used.'},'shape:Wide':{does:'Shift it early: second-man plays and quick hands to get your centres and wingers in space.',best:'Your edges and back three have the beating of their defence.',risk:'A well-drilled slide tracks the shift, and an up-and-in defence shuts it down before it starts.'},'tempo:Build':{does:'Complete your sets, kick long and squeeze them with field position until a chance comes.',best:'You are fitter and deeper than them, and your discipline holds up.',risk:'A side that wrestles at the ruck slows your sets and never lets the pressure build.'},'tempo:Balanced':{does:'Play what is in front of you: strike early when it is on, complete the set when it is not.',best:'Most matches.',risk:'Commits fully to neither.'},'tempo:Strike':{does:'Early ball movement, offloads and broken-play attack off a quick play-the-ball. High risk, high reward.',best:'Your halves and edges have the class to finish half-chances.',risk:'A quick, well-drilled line reads it, and every error hands them a set on your line.'},'attack:Middle':{does:'Win the ruck: big carries through the middle, quick play-the-balls, then go to the line on the back of momentum.',best:'Your middle forwards are stronger than theirs, or they defend with a slide.',risk:'A side that wrestles hard at the ruck slows your ball.'},'attack:Balanced':{does:'Mix carries through the middle with plays to the edges.',best:'You have no clear edge in the middle or out wide.',risk:'Leaves your biggest strength under-used.'},'attack:Edges':{does:'Go to the edges early with shapes and set plays. A faster game with more tries at both ends.',best:'Your edge attack is sharper than their edge defence.',risk:'An up-and-in defence, or a side with extra numbers in the line, shuts down the width.'},'kicking:Territory':{does:'Kick long, pin them in their own end and turn pressure into repeat sets and penalties.',best:'Your halves kick better than theirs, they rush up in defence, or they give away penalties.',risk:'A dangerous back three runs loose kicks back at you.'},'kicking:Balanced':{does:'Kick when it is on and run the last tackle when it is not.',best:'Evenly matched sides.',risk:'Little to exploit either way.'},'kicking:Possession':{does:'Keep the ball in hand: run the sixth tackle, offload and back your fitness. A faster game.',best:'You are fitter than them and your players hold on to the ball.',risk:'A side that wrestles at the ruck forces errors and wins the ball back.'},'defence:Rush':{does:'Up-and-in line speed to shut down the shift before the ball reaches the edges.',best:'They attack wide or keep the ball, and your defence is strong and fresh.',risk:'Kicks in behind catch you out, and tired legs or a weak defence get broken.'},'defence:Balanced':{does:'Hold shape and read the play.',best:'You are unsure how they will attack.',risk:'Never forces mistakes.'},'defence:Slide':{does:'Slide across the field to cover the width and the backfield.',best:'They attack wide or kick a lot.',risk:'Middle forwards carrying tight to the ruck find soft shoulders.'},'breakdown:Wrestle':{does:'Win the ruck: commit a third man, slow the play-the-ball and lie in.',best:'They play through the middle or keep the ball, and your ruck control is strong.',risk:'Poor discipline gives away six agains and penalties.'},'breakdown:Balanced':{does:'Slow it only when the tackle is won.',best:'Most matches.',risk:'Rarely wins the ruck.'},'breakdown:Get back':{does:'Release quickly and get numbers back in the line.',best:'They attack wide with their edges.',risk:'Middle-heavy and ball-in-hand sides get quick, easy play-the-balls.'}};"""

OPTION_NAME = r"""function optionName(ax,o){if(o==='Balanced')return `a balanced ${TACTIC_AXES[ax].toLowerCase()}`;return ({attack:{Middle:'an attack through the middle',Edges:'an edge attack'},kicking:{Territory:'the field-position kicking game',Possession:'ball in hand'},defence:{Rush:'up-and-in line speed',Slide:'the slide defence'},breakdown:{Wrestle:'wrestling at the ruck','Get back':'getting numbers back in the line'},shape:{Direct:'direct carries through the middle',Wide:'shifting it wide early'},tempo:{Build:'completing sets and building pressure',Strike:'early ball and broken play'}}[ax]||{})[o]||o}"""

PLAN_EFFECTS = r"""function planEffects(t,u,to,uo){const z=u.z,zo=uo.z,E=[],add=(axis,amt,text)=>{if(Math.abs(amt)>=.05)E.push({axis,amt,text})};
 if(t.attack==='Middle'){add('attack',clamp((z.pack-zo.pack)*1.5,-3,3),z.pack>=zo.pack?'carries through the middle against a softer pack':'carries into a stronger middle');if(to.defence==='Slide')add('attack',1,'soft shoulders close to the ruck against their slide');if(to.breakdown==='Wrestle'){const beaten=zo.breakdown>=z.pack-.3;add('attack',beaten?-1.2:.6,beaten?'their wrestle slowing your play-the-balls':'six agains and penalties they give away slowing your ruck')}if(to.breakdown==='Get back')add('attack',1,'quick play-the-balls they leave uncontested')}
 if(t.attack==='Edges'){add('attack',clamp((z.backs-zo.backs)*1.5,-3,3),z.backs>=zo.backs?'sharper edges than theirs':'running into sharper edge defence');if(to.defence==='Rush'){const smothered=zo.defence>=z.backs-.3;add('attack',smothered?-1.5:1,smothered?'their line speed smothering the shift':'beating their line speed on the edge')}if(to.defence==='Slide')add('attack',-.6,'their slide covering the width');if(to.breakdown==='Get back')add('attack',-.8,'extra numbers in their defensive line')}
 if(t.kicking==='Territory'){add('kicking',clamp((z.kicking-zo.kicking)*1.2,-2.5,2.5),z.kicking>=zo.kicking?'winning the field-position battle':'losing the kicking duel');if(to.defence==='Rush')add('kicking',1,'kicks in behind their line speed');if(zo.backThree>.2)add('kicking',-Math.min(2,zo.backThree*1.2),'their back three running kicks back');if(zo.discipline<-.3)add('kicking',Math.min(1.5,-zo.discipline),'pressure in their end forcing six agains and penalties')}
 if(t.kicking==='Possession'){add('kicking',clamp((z.backs+z.pack)/2-zo.defence,-2,2),(z.backs+z.pack)/2>=zo.defence?'ball in hand stretching their defence':'ball in hand running into a strong defence');add('kicking',clamp((u.fitness-uo.fitness)*.05,-1.5,1.5),u.fitness>=uo.fitness?'fresher legs in a fast game':'tired legs in a fast game');if(to.breakdown==='Wrestle'){const stolen=zo.breakdown>=0;add('kicking',stolen?-1.2:.5,stolen?'errors forced by their ruck wrestle':'six agains they concede wrestling')}if(to.defence==='Rush'){const shut=zo.defence>=z.backs;add('kicking',shut?-.8:.6,shut?'their line speed shutting down your sixth tackle plays':'your sixth tackle plays beating their line speed')}}
 if(t.shape==='Direct'){add('shape',clamp((z.pack-zo.pack)*1.2,-2.3,2.3),z.pack>=zo.pack?'go-forward carries into a lighter pack':'carries stopped short by a heavier pack');if(to.defence==='Rush')add('shape',-.9,'their line speed meeting the carrier behind the advantage line');if(to.breakdown==='Get back')add('shape',.9,'markers getting off the ruck early');if(to.breakdown==='Wrestle'){const beaten=zo.breakdown>=z.pack-.3;add('shape',beaten?-1.1:.5,beaten?'their wrestle slowing every carry':'six agains conceded wrestling against direct carries')}}
 if(t.shape==='Wide'){add('shape',clamp((z.backThree-zo.defence)*1.2,-2.3,2.3),z.backThree>=zo.defence?'outside backs with the pace to hurt them':'running into well-drilled edge defence');if(to.defence==='Slide')add('shape',-1,'their slide tracking you across the field');if(to.defence==='Rush'){const beaten=z.backThree>=zo.defence-.3;add('shape',beaten?.9:-.5,beaten?'space on the outside once their line speed is beaten':'their line speed cutting off the shift before it arrives')}}
 if(t.tempo==='Build'){add('tempo',clamp((u.fitness-uo.fitness)*.09,-2.2,2.2),u.fitness>=uo.fitness?'fresher legs as the completed sets pile up':'tiring legs as the sets pile up');if(to.breakdown==='Wrestle')add('tempo',-1,'their wrestle killing your momentum');add('tempo',clamp(u.discipline*.4,-1,1),u.discipline>=0?'discipline holding up over long spells of pressure':'errors creeping in over long spells of pressure')}
 if(t.tempo==='Strike'){add('tempo',clamp((z.backs-zo.defence)*1,-2.2,2.2),z.backs>=zo.defence?'class on the edges to finish a half-chance':'no space for broken play against a set defence');if(to.defence==='Rush')add('tempo',-1.1,'their line speed denying you early ball');if(to.breakdown==='Get back')add('tempo',.7,'quick play-the-balls to strike before their line resets')}
 if(t.defence==='Rush')add('defence',clamp(z.defence*.8,-1.5,1.5)-Math.max(0,80-u.fitness)*.06,z.defence>=0?'line speed from a strong defence':'rushing up with a defence not built for it');
 if(t.breakdown==='Wrestle')add('breakdown',clamp(z.breakdown*.6,-1.2,1.2)-Math.max(0,-z.discipline),z.discipline<0?'six agains and penalties conceded wrestling':'slow play-the-balls won at the ruck');
 return E}"""

RIVALRIES = r"""const RIVALRIES=[['South Sydney Rabbitohs','Sydney Roosters'],['Canterbury-Bankstown Bulldogs','Parramatta Eels'],['Brisbane Broncos','Dolphins'],['Brisbane Broncos','North Queensland Cowboys'],['Brisbane Broncos','Gold Coast Titans'],['Brisbane Broncos','Melbourne Storm'],['Penrith Panthers','Parramatta Eels'],['Manly Warringah Sea Eagles','Sydney Roosters'],['St George Illawarra Dragons','Cronulla-Sutherland Sharks'],['St George Illawarra Dragons','Sydney Roosters'],['Wests Tigers','Parramatta Eels'],['Newcastle Knights','Manly Warringah Sea Eagles'],['Canterbury-Bankstown Bulldogs','South Sydney Rabbitohs'],['Canberra Raiders','Canterbury-Bankstown Bulldogs'],['Melbourne Storm','Penrith Panthers'],['Hull FC','Hull Kingston Rovers'],['Wigan Warriors','St Helens'],['Leeds Rhinos','Bradford Bulls'],['Leeds Rhinos','Castleford Tigers'],['Castleford Tigers','Wakefield Trinity'],['Wigan Warriors','Leigh Leopards'],['Warrington Wolves','Wigan Warriors'],['Warrington Wolves','St Helens'],['Huddersfield Giants','Bradford Bulls'],['Catalans Dragons','Toulouse Olympique'],['York Knights','Hull FC']];"""

DISPLAY = r"""function displayTeam(t){return t}function short(t){return ({'Brisbane Broncos':'BRI','Canberra Raiders':'CAN','Canterbury-Bankstown Bulldogs':'CBY','Cronulla-Sutherland Sharks':'CRO','Dolphins':'DOL','Gold Coast Titans':'GLD','Manly Warringah Sea Eagles':'MAN','Melbourne Storm':'MEL','Newcastle Knights':'NEW','North Queensland Cowboys':'NQL','Parramatta Eels':'PAR','Penrith Panthers':'PEN','South Sydney Rabbitohs':'SOU','St George Illawarra Dragons':'SGI','Sydney Roosters':'SYD','New Zealand Warriors':'WAR','Wests Tigers':'WST','Bradford Bulls':'BRA','Castleford Tigers':'CAS','Catalans Dragons':'CAT','Huddersfield Giants':'HUD','Hull FC':'HFC','Hull Kingston Rovers':'HKR','Leeds Rhinos':'LEE','Leigh Leopards':'LEI','St Helens':'STH','Toulouse Olympique':'TOU','Wakefield Trinity':'WAK','Warrington Wolves':'WRR','Wigan Warriors':'WIG','York Knights':'YOR','New Zealand':'NZL','Papua New Guinea':'PNG','Cook Islands':'COK','New South Wales':'NSW','Queensland':'QLD','Australia':'AUS','England':'ENG','Tonga':'TGA','Samoa':'SAM','Fiji':'FIJ','France':'FRA','Lebanon':'LEB','Wales':'WAL','Ireland':'IRE','Scotland':'SCO','Italy':'ITA'})[t]||t.slice(0,3).toUpperCase()}"""
